<?php
/**
 * One-click site setup: Appearance → Truman Setup.
 *
 * Installs/activates Elementor, adds the photos to the Media Library, creates
 * the six pages (built with Elementor), the header/footer menus, and sets the
 * homepage and permalinks. Safe to run again: pages that already exist are
 * left alone unless "restore original content" is ticked.
 *
 * @package Truman_Enterprise
 */

defined( 'ABSPATH' ) || exit;

/**
 * Bundled site content (generated by wordpress/build.py).
 */
function truman_site_data() {
	static $data = null;
	if ( null === $data ) {
		$data = json_decode( file_get_contents( get_template_directory() . '/inc/site-data.json' ), true ); // phpcs:ignore WordPress.WP.AlternativeFunctions
	}
	return $data;
}

/* ------------------------------------------------------------------ admin UI */

function truman_setup_menu() {
	add_theme_page( __( 'Truman Setup', 'truman' ), __( 'Truman Setup', 'truman' ), 'manage_options', 'truman-setup', 'truman_setup_page' );
}
add_action( 'admin_menu', 'truman_setup_menu' );

// Go straight to the setup screen after the theme is activated.
function truman_after_switch_theme() {
	if ( ! get_option( 'truman_setup_done' ) ) {
		set_transient( 'truman_show_setup', 1, 120 );
	}
}
add_action( 'after_switch_theme', 'truman_after_switch_theme' );

function truman_maybe_redirect_to_setup() {
	if ( ! get_transient( 'truman_show_setup' ) || wp_doing_ajax() || ! current_user_can( 'manage_options' ) ) {
		return;
	}
	delete_transient( 'truman_show_setup' );
	wp_safe_redirect( admin_url( 'themes.php?page=truman-setup' ) );
	exit;
}
add_action( 'admin_init', 'truman_maybe_redirect_to_setup' );

function truman_setup_notice() {
	if ( get_option( 'truman_setup_done' ) || ! current_user_can( 'manage_options' ) ) {
		return;
	}
	$screen = get_current_screen();
	if ( $screen && 'appearance_page_truman-setup' === $screen->id ) {
		return;
	}
	printf(
		'<div class="notice notice-info"><p><strong>%s</strong> %s <a class="button button-primary" href="%s">%s</a></p></div>',
		esc_html__( 'Truman Enterprise theme:', 'truman' ),
		esc_html__( 'one more step to build the site.', 'truman' ),
		esc_url( admin_url( 'themes.php?page=truman-setup' ) ),
		esc_html__( 'Run setup', 'truman' )
	);
}
add_action( 'admin_notices', 'truman_setup_notice' );

function truman_setup_page() {
	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}
	$done = get_option( 'truman_setup_done' );
	$log  = get_transient( 'truman_setup_log' );
	?>
	<div class="wrap" style="max-width:760px">
		<h1><?php esc_html_e( 'Truman Enterprise — Site Setup', 'truman' ); ?></h1>

		<?php if ( $log && isset( $_GET['done'] ) ) : // phpcs:ignore WordPress.Security.NonceVerification ?>
			<?php delete_transient( 'truman_setup_log' ); ?>
			<div class="notice notice-success" style="padding:12px 16px">
				<p style="font-size:15px"><strong><?php esc_html_e( 'Setup complete.', 'truman' ); ?></strong>
					<a class="button button-primary" style="margin-left:8px" href="<?php echo esc_url( home_url( '/' ) ); ?>" target="_blank"><?php esc_html_e( 'View the site', 'truman' ); ?></a></p>
				<ul style="list-style:disc;padding-left:20px">
					<?php foreach ( $log as $entry ) : ?>
						<li style="<?php echo 'warn' === $entry[0] ? 'color:#b32d2e' : ''; ?>"><?php echo esc_html( $entry[1] ); ?></li>
					<?php endforeach; ?>
				</ul>
			</div>
		<?php endif; ?>

		<p style="font-size:14px"><?php esc_html_e( 'This builds the Truman Enterprise Narrowboat Trust website in one go:', 'truman' ); ?></p>
		<ul style="list-style:disc;padding-left:20px;font-size:14px">
			<li><?php esc_html_e( 'Installs and activates the free Elementor page builder (if needed)', 'truman' ); ?></li>
			<li><?php esc_html_e( 'Installs the Truman Boat Bookings calendar', 'truman' ); ?></li>
			<li><?php esc_html_e( 'Adds the site photos to the Media Library', 'truman' ); ?></li>
			<li><?php esc_html_e( 'Creates the pages: Home, Our Trips, Get Involved, Support Us, Contact, Book a Trip', 'truman' ); ?></li>
			<li><?php esc_html_e( 'Creates the header and footer menus', 'truman' ); ?></li>
			<li><?php esc_html_e( 'Sets Home as the homepage and switches on tidy links (/our-trips/)', 'truman' ); ?></li>
		</ul>

		<form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" style="margin-top:20px">
			<?php wp_nonce_field( 'truman_setup' ); ?>
			<input type="hidden" name="action" value="truman_setup">
			<?php if ( $done ) : ?>
				<p><label><input type="checkbox" name="truman_restore" value="1">
					<?php esc_html_e( 'Restore the original content of the Truman pages (overwrites any edits you have made to them)', 'truman' ); ?></label></p>
			<?php endif; ?>
			<p><button type="submit" class="button button-primary button-hero">
				<?php echo $done ? esc_html__( 'Run setup again', 'truman' ) : esc_html__( 'Set up the site', 'truman' ); ?>
			</button></p>
			<p class="description"><?php esc_html_e( 'Takes up to a minute. Please don’t close the page.', 'truman' ); ?></p>
		</form>
	</div>
	<?php
}

/* ------------------------------------------------------------------ runner */

function truman_handle_setup() {
	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( esc_html__( 'Sorry, you are not allowed to do that.', 'truman' ) );
	}
	check_admin_referer( 'truman_setup' );
	if ( function_exists( 'set_time_limit' ) ) {
		@set_time_limit( 300 ); // phpcs:ignore WordPress.PHP.NoSilencedErrors
	}
	$restore = ! empty( $_POST['truman_restore'] );
	$log     = array();

	$log[]  = truman_ensure_elementor();
	$log[]  = truman_ensure_bookings();
	$images = truman_import_images( $log );
	$pages  = truman_create_pages( $images, $restore, $log );
	truman_create_menus( $pages, $log );
	truman_site_settings( $pages, $log );

	update_option( 'truman_setup_done', time() );
	set_transient( 'truman_setup_log', $log, 600 );
	wp_safe_redirect( admin_url( 'themes.php?page=truman-setup&done=1' ) );
	exit;
}
add_action( 'admin_post_truman_setup', 'truman_handle_setup' );

/**
 * @return array{0:string,1:string} [ 'ok'|'warn', message ]
 */
function truman_ensure_elementor() {
	require_once ABSPATH . 'wp-admin/includes/plugin.php';
	$file = 'elementor/elementor.php';

	if ( is_plugin_active( $file ) ) {
		return array( 'ok', __( 'Elementor is already active.', 'truman' ) );
	}

	if ( ! file_exists( WP_PLUGIN_DIR . '/' . $file ) ) {
		if ( ! current_user_can( 'install_plugins' ) ) {
			return array( 'warn', __( 'Elementor is not installed and this account cannot install plugins. Install Elementor from Plugins → Add New, then run setup again.', 'truman' ) );
		}
		require_once ABSPATH . 'wp-admin/includes/file.php';
		require_once ABSPATH . 'wp-admin/includes/misc.php';
		require_once ABSPATH . 'wp-admin/includes/plugin-install.php';
		require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php';

		$api = plugins_api( 'plugin_information', array( 'slug' => 'elementor', 'fields' => array( 'sections' => false ) ) );
		if ( is_wp_error( $api ) ) {
			return array( 'warn', sprintf( __( 'Could not download Elementor (%s). Install it from Plugins → Add New, then run setup again.', 'truman' ), wp_strip_all_tags( $api->get_error_message() ) ) );
		}
		$upgrader = new Plugin_Upgrader( new WP_Ajax_Upgrader_Skin() );
		$result   = $upgrader->install( $api->download_link );
		if ( is_wp_error( $result ) || ! $result || ! file_exists( WP_PLUGIN_DIR . '/' . $file ) ) {
			$msg = is_wp_error( $result ) ? wp_strip_all_tags( $result->get_error_message() ) : __( 'unknown error', 'truman' );
			return array( 'warn', sprintf( __( 'Elementor could not be installed (%s). Install it from Plugins → Add New, then run setup again.', 'truman' ), $msg ) );
		}
	}

	$activated = activate_plugin( $file );
	delete_transient( 'elementor_activation_redirect' ); // stay on the setup results, not Elementor's welcome wizard
	if ( is_wp_error( $activated ) ) {
		return array( 'warn', sprintf( __( 'Elementor could not be activated: %s', 'truman' ), $activated->get_error_message() ) );
	}
	return array( 'ok', __( 'Elementor installed and activated.', 'truman' ) );
}

/**
 * Install and activate the bundled Truman Boat Bookings plugin.
 *
 * @return array{0:string,1:string}
 */
function truman_ensure_bookings() {
	require_once ABSPATH . 'wp-admin/includes/plugin.php';
	$file = 'truman-bookings/truman-bookings.php';
	if ( is_plugin_active( $file ) ) {
		return array( 'ok', __( 'The booking calendar is already active.', 'truman' ) );
	}
	if ( ! file_exists( WP_PLUGIN_DIR . '/' . $file ) ) {
		$zip = get_template_directory() . '/inc/truman-bookings.zip';
		if ( ! file_exists( $zip ) || ! current_user_can( 'install_plugins' ) ) {
			return array( 'warn', __( 'The booking calendar plugin could not be installed. Upload truman-bookings.zip in Plugins → Add New → Upload Plugin.', 'truman' ) );
		}
		require_once ABSPATH . 'wp-admin/includes/file.php';
		require_once ABSPATH . 'wp-admin/includes/misc.php';
		require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php';
		$upgrader = new Plugin_Upgrader( new WP_Ajax_Upgrader_Skin() );
		$result   = $upgrader->install( $zip );
		if ( is_wp_error( $result ) || ! $result || ! file_exists( WP_PLUGIN_DIR . '/' . $file ) ) {
			return array( 'warn', __( 'The booking calendar plugin could not be installed. Upload truman-bookings.zip in Plugins → Add New → Upload Plugin.', 'truman' ) );
		}
	}
	$activated = activate_plugin( $file );
	if ( is_wp_error( $activated ) ) {
		return array( 'warn', sprintf( __( 'The booking calendar could not be activated: %s', 'truman' ), $activated->get_error_message() ) );
	}
	return array( 'ok', __( 'Booking calendar installed (Boat Bookings in the admin menu).', 'truman' ) );
}

/**
 * Copy the bundled photos into the Media Library.
 *
 * @return array filename => URL
 */
function truman_import_images( array &$log ) {
	require_once ABSPATH . 'wp-admin/includes/file.php';
	require_once ABSPATH . 'wp-admin/includes/media.php';
	require_once ABSPATH . 'wp-admin/includes/image.php';

	$urls   = array();
	$added  = 0;
	$failed = array();
	foreach ( truman_site_data()['images'] as $file => $alt ) {
		$existing = get_posts(
			array(
				'post_type'      => 'attachment',
				'post_status'    => 'any',
				'meta_key'       => '_truman_asset', // phpcs:ignore WordPress.DB.SlowDBQuery
				'meta_value'     => $file, // phpcs:ignore WordPress.DB.SlowDBQuery
				'posts_per_page' => 1,
				'fields'         => 'ids',
			)
		);
		if ( $existing ) {
			$id = $existing[0];
		} else {
			$tmp = wp_tempnam( $file );
			copy( get_template_directory() . '/assets/images/' . $file, $tmp );
			$id = media_handle_sideload( array( 'name' => $file, 'tmp_name' => $tmp ), 0, $alt );
			if ( is_wp_error( $id ) ) {
				@unlink( $tmp ); // phpcs:ignore
				$failed[] = $file;
				$urls[ $file ] = get_template_directory_uri() . '/assets/images/' . $file;
				continue;
			}
			update_post_meta( $id, '_wp_attachment_image_alt', $alt );
			update_post_meta( $id, '_truman_asset', $file );
			$added++;
		}
		$urls[ $file ] = wp_get_attachment_url( $id );
	}
	if ( $failed ) {
		$log[] = array( 'warn', sprintf( __( 'These photos could not be added to the Media Library and are served from the theme instead: %s', 'truman' ), implode( ', ', $failed ) ) );
	}
	if ( $added ) {
		$log[] = array( 'ok', sprintf( _n( '%d photo added to the Media Library.', '%d photos added to the Media Library.', $added, 'truman' ), $added ) );
	} elseif ( ! $failed ) {
		$log[] = array( 'ok', __( 'Photos are already in the Media Library.', 'truman' ) );
	}
	return $urls;
}

/**
 * Replace build placeholders with this site's URLs.
 */
function truman_fill( $text, array $images ) {
	$text = str_replace( '%%HOME%%', trailingslashit( home_url() ), $text );
	return preg_replace_callback(
		'/%%IMG:([^%]+)%%/',
		function ( $m ) use ( $images ) {
			return isset( $images[ $m[1] ] ) ? $images[ $m[1] ] : get_template_directory_uri() . '/assets/images/' . $m[1];
		},
		$text
	);
}

/**
 * Tag each photo with its Media Library ID (class wp-image-N size-full) so
 * volunteers can swap it with Image details → Replace in the page editor.
 * Works on JSON-encoded Elementor data, where quotes appear as \\".
 */
function truman_tag_images( $text ) {
	return preg_replace_callback(
		'/<img\b[^>]*>/',
		function ( $m ) {
			$tag = $m[0];
			if ( false !== strpos( $tag, 'wp-image-' ) || ! preg_match( '/src=\\\\?"(.*?)\\\\?"/', $tag, $src ) ) {
				return $tag;
			}
			$id = attachment_url_to_postid( stripslashes( $src[1] ) );
			if ( ! $id ) {
				return $tag;
			}
			$add = 'wp-image-' . $id . ' size-full';
			if ( preg_match( '/class=\\\\?"/', $tag ) ) {
				return preg_replace( '/class=(\\\\?")/', 'class=${1}' . $add . ' ', $tag, 1 );
			}
			$q = false !== strpos( $tag, '\\"' ) ? '\\"' : '"';
			return '<img class=' . $q . $add . $q . substr( $tag, 4 );
		},
		$text
	);
}

/**
 * @return array key => page ID
 */
function truman_create_pages( array $images, $restore, array &$log ) {
	$ids      = array();
	$created  = 0;
	$restored = 0;
	$version  = defined( 'ELEMENTOR_VERSION' ) ? ELEMENTOR_VERSION : '3.25.0';

	foreach ( truman_site_data()['pages'] as $p ) {
		$page = truman_find_page( $p['key'] );

		if ( ! $page ) {
			// A different page already using this address? Move it aside (kept as a draft).
			$clash = get_page_by_path( $p['slug'] );
			if ( $clash ) {
				wp_update_post( array( 'ID' => $clash->ID, 'post_name' => $p['slug'] . '-old', 'post_status' => 'draft' ) );
				$log[] = array( 'warn', sprintf( __( 'An existing page “%1$s” used the address /%2$s/ — it has been kept as a draft named %2$s-old.', 'truman' ), $clash->post_title, $p['slug'] ) );
			}
		} elseif ( ! $restore ) {
			$ids[ $p['key'] ] = $page->ID;
			continue;
		}

		$postarr = array(
			'post_type'    => 'page',
			'post_status'  => 'publish',
			'post_title'   => $p['title'],
			'post_name'    => $p['slug'],
			'post_content' => truman_fill( $p['html'], $images ),
			'menu_order'   => $p['order'],
		);
		if ( $page ) {
			$postarr['ID'] = $page->ID;
		}
		$id = wp_insert_post( wp_slash( $postarr ), true );
		if ( is_wp_error( $id ) ) {
			$log[] = array( 'warn', sprintf( __( 'Could not create the %1$s page: %2$s', 'truman' ), $p['title'], $id->get_error_message() ) );
			continue;
		}

		update_post_meta( $id, '_truman_page', $p['key'] );
		update_post_meta( $id, '_wp_page_template', 'elementor_header_footer' );
		update_post_meta( $id, '_elementor_edit_mode', 'builder' );
		update_post_meta( $id, '_elementor_template_type', 'wp-page' );
		update_post_meta( $id, '_elementor_version', $version );
		update_post_meta( $id, '_elementor_page_settings', array( 'hide_title' => 'yes' ) );
		update_post_meta( $id, '_elementor_data', wp_slash( truman_tag_images( truman_fill( $p['elementor'], $images ) ) ) );
		delete_post_meta( $id, '_elementor_css' );

		$ids[ $p['key'] ] = $id;
		$page ? $restored++ : $created++;
	}

	if ( $created ) {
		$log[] = array( 'ok', sprintf( _n( '%d page created.', '%d pages created.', $created, 'truman' ), $created ) );
	}
	if ( $restored ) {
		$log[] = array( 'ok', sprintf( _n( '%d page restored to its original content.', '%d pages restored to their original content.', $restored, 'truman' ), $restored ) );
	}
	if ( ! $created && ! $restored ) {
		$log[] = array( 'ok', __( 'All pages already exist — left unchanged.', 'truman' ) );
	}
	return $ids;
}

function truman_find_page( $key ) {
	$found = get_posts(
		array(
			'post_type'      => 'page',
			'post_status'    => array( 'publish', 'draft', 'private', 'pending' ),
			'meta_key'       => '_truman_page', // phpcs:ignore WordPress.DB.SlowDBQuery
			'meta_value'     => $key, // phpcs:ignore WordPress.DB.SlowDBQuery
			'posts_per_page' => 1,
		)
	);
	return $found ? $found[0] : null;
}

function truman_create_menus( array $pages, array &$log ) {
	$data      = truman_site_data();
	$locations = get_theme_mod( 'nav_menu_locations', array() );
	$made      = 0;

	foreach ( array( 'primary' => __( 'Main menu', 'truman' ), 'footer' => __( 'Footer menu', 'truman' ) ) as $location => $name ) {
		if ( ! empty( $locations[ $location ] ) && wp_get_nav_menu_object( $locations[ $location ] ) ) {
			continue; // already has a menu — respect it
		}
		$menu = wp_get_nav_menu_object( $name );
		if ( $menu ) {
			$menu_id = $menu->term_id;
		} else {
			$menu_id = wp_create_nav_menu( $name );
			if ( is_wp_error( $menu_id ) ) {
				$log[] = array( 'warn', sprintf( __( 'Could not create the %s.', 'truman' ), $name ) );
				continue;
			}
			foreach ( $data['menus'][ $location ] as $i => $item ) {
				if ( empty( $pages[ $item['key'] ] ) ) {
					continue;
				}
				wp_update_nav_menu_item(
					$menu_id,
					0,
					array(
						'menu-item-title'     => $item['label'],
						'menu-item-object'    => 'page',
						'menu-item-object-id' => $pages[ $item['key'] ],
						'menu-item-type'      => 'post_type',
						'menu-item-status'    => 'publish',
						'menu-item-classes'   => isset( $item['class'] ) ? $item['class'] : '',
						'menu-item-position'  => $i + 1,
					)
				);
			}
			$made++;
		}
		$locations[ $location ] = $menu_id;
	}
	set_theme_mod( 'nav_menu_locations', $locations );
	if ( $made ) {
		$log[] = array( 'ok', __( 'Header and footer menus created (Appearance → Menus).', 'truman' ) );
	}
}

function truman_site_settings( array $pages, array &$log ) {
	global $wp_rewrite;

	if ( ! empty( $pages['home'] ) ) {
		update_option( 'show_on_front', 'page' );
		update_option( 'page_on_front', $pages['home'] );
		$log[] = array( 'ok', __( 'Home is set as the homepage.', 'truman' ) );
	}

	if ( ! get_option( 'permalink_structure' ) ) {
		$wp_rewrite->set_permalink_structure( '/%postname%/' );
		$log[] = array( 'ok', __( 'Page addresses switched to tidy links (e.g. /our-trips/).', 'truman' ) );
	}
	flush_rewrite_rules();

	// Let the theme's fonts and colours apply inside Elementor widgets.
	update_option( 'elementor_disable_color_schemes', 'yes' );
	update_option( 'elementor_disable_typography_schemes', 'yes' );

	if ( class_exists( '\Elementor\Plugin' ) && isset( \Elementor\Plugin::$instance->files_manager ) ) {
		\Elementor\Plugin::$instance->files_manager->clear_cache();
	}
}
